using Microsoft.VisualStudio.TestTools.UnitTesting;
using Contoso.Text;

[TestClass]
public sealed class StringFormatterTests
{
    private readonly StringFormatter _formatter = new();

    [TestMethod]
    [DataRow("5551234567")]
    [DataRow("8005559999")]
    public void FormatPhoneNumber_ValidDigits_StartsWithAreaCodeInParens(string digits)
    {
        var result = _formatter.FormatPhoneNumber(digits);

        Assert.StartsWith($"({digits[..3]})", result);
    }

    [TestMethod]
    [DataRow("5551234567", "4567")]
    [DataRow("8005559999", "9999")]
    public void FormatPhoneNumber_ValidDigits_EndsWithLastFour(string digits, string lastFour)
    {
        var result = _formatter.FormatPhoneNumber(digits);

        Assert.EndsWith(lastFour, result);
    }

    [TestMethod]
    [DataRow("5551234567", "(555) 123-4567")]
    [DataRow("8005559999", "(800) 555-9999")]
    public void FormatPhoneNumber_ValidDigits_ReturnsFormattedNumber(string digits, string expected)
    {
        var result = _formatter.FormatPhoneNumber(digits);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void FormatPhoneNumber_Null_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => _formatter.FormatPhoneNumber(null!));
        Assert.AreEqual("digits", ex.ParamName);
    }

    [TestMethod]
    [DataRow("123")]
    [DataRow("12345678901")]
    public void FormatPhoneNumber_WrongLength_ThrowsArgumentException(string digits)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _formatter.FormatPhoneNumber(digits));
    }

    [TestMethod]
    [DataRow("Alice", "Mr.")]
    [DataRow("Bob", "Dr.")]
    public void BuildGreeting_ValidInput_StartsWithDear(string name, string title)
    {
        var result = _formatter.BuildGreeting(name, title);

        Assert.StartsWith("Dear", result);
    }

    [TestMethod]
    [DataRow("Alice", "Mr.")]
    [DataRow("Bob", "Dr.")]
    public void BuildGreeting_ValidInput_EndsWithNameAndComma(string name, string title)
    {
        var result = _formatter.BuildGreeting(name, title);

        Assert.EndsWith($"{name},", result);
    }

    [TestMethod]
    public void BuildGreeting_DefaultTitle_UsesHonorific()
    {
        var result = _formatter.BuildGreeting("Smith");

        Assert.AreEqual("Dear Mr. Smith,", result);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void BuildGreeting_NullOrWhiteSpace_Throws(string? name)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _formatter.BuildGreeting(name!));
    }

    [TestMethod]
    [DataRow("Hello World", "hello-world")]
    [DataRow("  My Blog Post!  ", "my-blog-post")]
    [DataRow("C# is Great!!!", "c-is-great")]
    public void GenerateSlug_ValidTitle_ReturnsExpectedSlug(string title, string expected)
    {
        var result = _formatter.GenerateSlug(title);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void GenerateSlug_MultiWordTitle_ContainsHyphen()
    {
        var result = _formatter.GenerateSlug("Hello World");

        Assert.Contains("-", result);
    }

    [TestMethod]
    public void GenerateSlug_NullOrWhiteSpace_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(() => _formatter.GenerateSlug(""));
    }

    [TestMethod]
    [DataRow(9.99, "$", "$9.99")]
    [DataRow(1000, "€", "€1000.00")]
    [DataRow(0, "$", "$0.00")]
    public void FormatCurrency_ReturnsSymbolWithAmount(decimal amount, string symbol, string expected)
    {
        var result = _formatter.FormatCurrency(amount, symbol);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    [DataRow("$")]
    [DataRow("€")]
    [DataRow("£")]
    public void FormatCurrency_StartsWithSymbol(string symbol)
    {
        var result = _formatter.FormatCurrency(42.50m, symbol);

        Assert.StartsWith(symbol, result);
    }

    [TestMethod]
    public void FormatCurrency_AlwaysEndsWith2DecimalPlaces()
    {
        var result = _formatter.FormatCurrency(10m);

        Assert.EndsWith(".00", result);
    }

    [TestMethod]
    public void FormatCurrency_FractionalAmount_EndsWithDecimals()
    {
        var result = _formatter.FormatCurrency(19.5m);

        Assert.EndsWith(".50", result);
    }
}

